from review import card,save,DATE

def b(t,s,r=None):
 d=dict(title=t,text=s)
 if r:d['citation']=r
 return d
def sm(s,r):return dict(sentences=s,basis='saved_sources',source_basis='source-text',written_on=DATE,source_refs=r)
def imp(c,s):return dict(score=c['importance']['score'],method='editorial',reason=s+' Existing numerical score retained.',assessed_on=DATE)

i='TCS-2506';_,c=card(i);refs=c['references'];refs[0]['locator']='CCC 2023, article 28: Section 2.1 and page 28:16, “Lower bounds for higher-depth formulas”. The omitted containment is VF ⊆ VBP, not one of the intermediate formula classes on the previous page. The source works over a field F without a characteristic restriction.'
refs.append(dict(id='multilinear2026',title='Multilinear Algebraic Branching Programs and the Min-Partition Rank Method',authors='Théo Borém Fabris, Nutan Limaye, Srikanth Srinivasan, Amir Yehudayoff',year=2026,url='https://eccc.weizmann.ac.il/report/2026/001/',locator='ECCC TR26-001, 1 January 2026: introduction and model definitions read. Recounts the general VF ⊆ VBP ⊆ VP hierarchy and the known separation restricted to syntactically multilinear computation.'))
save(i,dict(title='Are algebraic branching programs stronger than formulas?',formal='For a fixed field F, is VF_F a proper subclass of VBP_F? Equivalently, is there a family (fₙ) of polynomials of polynomially bounded degree in polynomially many commuting variables that has polynomial-size algebraic branching programs over F but no polynomial-size algebraic formulas over F? The field is a parameter of the question, as in the source; a result must state the fields to which it applies.',definitions='A polynomial family has fₙ∈F[x₁,…,x_{m(n)}], where m(n) and the total degree of fₙ are at most n^a+a for some fixed a. An algebraic formula is a finite rooted tree whose leaves are variables or constants in F and whose internal gates are binary addition or multiplication. Its output is a formal polynomial; equality means coefficientwise equality in F[x], also when F is finite. Its size is its number of nodes. An algebraic branching program is a finite directed acyclic graph with a designated source and sink and affine-linear polynomial labels on edges. It computes the sum, over all source-to-sink paths, of the product of the labels on that path. Count vertices, edges and the nonzero coefficients used to describe edge labels as its size; these choices differ only polynomially from the usual size conventions. Field constants have unit algebraic cost, with no bit-length bound. VF_F and VBP_F consist respectively of the polynomial families with formula size and branching-program size bounded by n^b+b for some constant b independent of n. These are nonuniform classes: a different finite computation may be chosen for each n, with no requirement to generate it algorithmically. The separation asks for one family in VBP_F for which, for every b, some n requires formula size greater than n^b+b. There is no restriction to multilinear computation, bounded depth, homogeneous intermediate gates or noncommuting variables.',question_type='yes_no',answer_criterion='For the stated field F, prove VF_F ⊊ VBP_F by exhibiting a family in VBP_F and proving that its formula sizes are not polynomially bounded, or prove VF_F=VBP_F by showing that every polynomial-size branching-program family has polynomial-size formulas. Any characteristic or field restriction must be stated as part of the scope of the answer. A lower bound only for bounded-depth or multilinear formulas does not resolve the unrestricted question.',context_blocks=[b('Two ways of sharing arithmetic work','A formula is a tree: an intermediate result used in two places must be copied. A branching program can share subpaths, and its output combines the products along all paths.'),b('The easy containment is known','Every polynomial-size algebraic formula has a polynomial-size branching program. The question is whether this containment hides a strict difference in expressive power.', 'primary'),b('The source’s depth lower bound is restricted','The source discusses a branching-program family that already requires more than a particular small depth in polynomial-size formulas. That does not rule out polynomial-size formulas of unrestricted depth.', 'primary'),b('Multilinear separations address a smaller model','The January 2026 paper recalls a known separation between syntactically multilinear formulas and branching programs. An unrestricted formula computing a multilinear output need not itself be syntactically multilinear, so that theorem does not settle VF versus VBP.', 'multilinear2026')],why='Separates two fundamental models of algebraic computation and asks whether sharing path computations gives a polynomial-versus-superpolynomial advantage over arithmetic trees.',references=refs,progress=[dict(date='2023',text='The source explicitly records VF ⊆ VBP as a containment whose strictness is unknown and distinguishes it from depth-restricted lower bounds.',citation='primary'),dict(date='2026-01-01',text='The later paper studies the restricted multilinear hierarchy and recounts its known formula-versus-branching-program separation; it does not claim the general separation.',citation='multilinear2026')],status='source_open',status_note='Recovered the exact containment from the source and checked subsequent work through 12 September 2026, including the January 2026 multilinear paper. No unrestricted resolution was located. The May revision notice for ECCC TR26-043 reports a gap in that separate barrier claim, which is not used as an established result here.',model_self_contained=True,requires_context=False,importance=imp(c,'A basic separation in the algebraic complexity hierarchy, comparing formulas with reusable path computations.'),review_note='Replaced a pronoun-only extraction by VF versus VBP. Defined the nonuniform classes, formal polynomial equality and size conventions; kept the source field as an explicit parameter and removed suggested depth-lower-bound routes.',working_summary=sm(['Algebraic formulas compute polynomials using arithmetic trees.','Algebraic branching programs compute sums of products along paths and can share subcomputations.','Every polynomial-size formula can be represented by a polynomial-size branching program.','The question asks whether some branching-program family requires superpolynomial formula size over the specified field.','Known results for bounded-depth or syntactically multilinear formulas do not settle this unrestricted separation.'],['primary','multilinear2026'])),notes=['Recovered VF ⊆ VBP from the correct paragraph.','Defined the field-dependent nonuniform classes, formal equality and polynomial-size quantifiers.','Distinguished commuting, unrestricted computation from bounded-depth and multilinear variants.','Checked the January 2026 paper and the gap notice on a separate later barrier claim.'],checked_sources=[r['url'] for r in refs]+['https://eccc.weizmann.ac.il/report/2026/043/'])

i='TCS-2535';_,c=card(i);refs=c['references'];refs[0]['locator']='RANDOM 2023, article 61: definitions in Section 1, Theorem 1.2 and Conjecture 1.8 on page 61:7. The missing right-hand side is the expectation of the pointwise Euclidean norm of the negative gradient.'
refs.extend([dict(id='directed2024',title='Directed Isoperimetry and Monotonicity Testing: A Dynamical Approach',authors='Renato Ferreira Pinto Jr.',year=2024,url='https://arxiv.org/abs/2404.17882',locator='FOCS 2024; arXiv v2, 1 October 2024: Theorem 1.1 and Section 1.3 read. Proves the directed (L²,ℓ₂) inequality and explicitly states that the (L¹,ℓ₂) Conjecture 1.8 is not resolved.'),dict(id='directed_thesis2025',title='Analytic Property Testing: Directed Isoperimetry and Monotonicity',authors='Renato Ferreira Pinto Jr.',year=2025,url='https://uwspace.uwaterloo.ca/items/e1f421e1-2f50-4ef9-af1e-45cdc345e24d',locator='PhD thesis, University of Waterloo, 3 July 2025: Table 3.1 and Conjecture 4.43, printed page 60, read. Retains the same continuous (L¹,ℓ₂) conjecture after the later tester result.')])
save(i,dict(title='A dimension-free directed L¹ Poincaré inequality',formal='Does there exist an absolute constant C<∞ such that, for every integer n≥1 and every Lipschitz function f:[0,1]ⁿ→ℝ, d₁^mono(f) ≤ C ∫_[0,1]ⁿ (Σ_{i=1}^n max{−∂ᵢf(x),0}²)^{1/2} dx? Here d₁^mono(f) is the L¹ distance to the coordinatewise nondecreasing functions. The same C must work for every dimension and every finite Lipschitz constant.',definitions='Lebesgue measure on [0,1]ⁿ has total mass one. A function g:[0,1]ⁿ→ℝ is coordinatewise nondecreasing if g(x)≤g(y) whenever xᵢ≤yᵢ for all i. Define d₁^mono(f)=inf_g ∫|f(x)−g(x)|dx, over measurable integrable coordinatewise nondecreasing g; g need not have the same Lipschitz constant as f. A function f is Lipschitz if there is a finite L with |f(x)−f(y)|≤L‖x−y‖₂ for all x,y in the cube. Its gradient exists almost everywhere; its values on the exceptional null set may be set to zero without changing any integral. The negative gradient is ∇⁻f(x)=(max{−∂₁f(x),0},…,max{−∂ₙf(x),0}). The right-hand side is C·E[‖∇⁻f(X)‖₂] for a uniform point X in the cube. It is not C·(E[‖∇⁻f(X)‖₂²])^{1/2}. No boundary condition, mean-zero assumption or fixed bound on the range of f is imposed.',question_type='yes_no',answer_criterion='Prove the displayed inequality with one universal finite C, or refute the existence of such a C by showing that the ratio d₁^mono(f)/E‖∇⁻f‖₂ is unbounded across the stated functions and dimensions (including a function with positive distance and zero denominator, if one existed). A bound whose constant grows with n, or a bound using the L² norm of the gradient over the cube, is insufficient.',context_blocks=[b('A local violation versus a global repair','A negative partial derivative witnesses a local decrease in one coordinate. The left-hand side measures the least average change to the entire function needed to remove all monotonicity violations.'),b('The dimension-free Euclidean norm is the missing improvement','The 2023 source proves a directed inequality using E‖∇⁻f‖₁. Comparing ℓ₁ and ℓ₂ norms yields a bound with a factor √n, whereas the conjecture asks to remove all dependence on dimension.', 'primary'),b('The 2024 theorem uses a different outer norm','The later theorem bounds squared L² distance to monotonicity by C·E‖∇⁻f‖₂². Even though L² distance dominates L¹ distance, the square root of this second moment can be much larger than E‖∇⁻f‖₂. The author explicitly leaves the present conjecture open.', 'directed2024'),b('The conjecture survived the improved tester','The 2025 thesis restates the inequality after obtaining a tester with sublinear dimension dependence from the L² theorem. Thus the motivating algorithmic progress and the analytic conjecture have distinct statuses.', 'directed_thesis2025')],why='Would connect local directional decreases to global distance from monotonicity with a universal constant, extending a central isoperimetric principle to real-valued functions on continuous cubes.',references=refs,progress=[dict(date='2023',text='The directed (L¹,ℓ₁) inequality is proved; the dimension-free (L¹,ℓ₂) version is Conjecture 1.8.',citation='primary'),dict(date='2024',text='The directed (L²,ℓ₂) theorem yields improved testing bounds but explicitly does not settle this conjecture.',citation='directed2024'),dict(date='2025-07-03',text='The thesis retains the same statement as Conjecture 4.43.',citation='directed_thesis2025')],status='source_open',status_note='The full 2023 conjecture, October 2024 preprint revision and July 2025 thesis were checked, including the explicit statement that the later norm inequality does not resolve this one. Searches through 12 September 2026 located no resolution of the full continuous-cube claim.',model_self_contained=True,requires_context=False,importance=imp(c,'A dimension-free analytic relationship between local violations and global distance from monotonicity, with significance for property testing.'),review_note='Restored the missing inequality, all quantifiers, uniform measure, negative derivative and outer L¹ norm. Separated the later L² theorem and tester from the original conjecture.',working_summary=sm(['The conjecture concerns every Lipschitz real-valued function on a continuous unit cube.','It asks whether average distance to a monotone function is controlled by the average Euclidean magnitude of the negative gradient.','The multiplicative constant must be independent of the dimension and the Lipschitz constant.','A known inequality using the sum of coordinate decreases loses a square-root dimension factor.','Later work proves a different inequality using squared quantities and explicitly leaves this conjecture open.'],['primary','directed2024','directed_thesis2025'])),notes=['Recovered the exact dimension-free (L¹,ℓ₂) inequality from Conjecture 1.8.','Defined monotone distance, Lipschitz functions, almost-everywhere negative gradient and measure.','Distinguished the expectation of a norm from the square root of its second moment.','Checked the explicit 2024 non-resolution and the 2025 thesis restatement.'],checked_sources=[r['url'] for r in refs]+['https://drops.dagstuhl.de/entities/document/10.4230/LIPIcs.ICALP.2026.14'])
